const crypto = require('node:crypto');

// 每用户独立随机盐 + scrypt 慢哈希，存储格式 salt:hash
function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const derived = crypto.scryptSync(password, salt, 64).toString('hex');
  return salt + ':' + derived;
}

function verifyPassword(password, stored) {
  const arr = stored.split(':');
  const salt = arr[0], hash = arr[1];
  const expected = Buffer.from(hash, 'hex');
  const actual = crypto.scryptSync(password, salt, 64);
  return expected.length === actual.length && crypto.timingSafeEqual(expected, actual);
}

const stored = hashPassword('P@ssw0rd!');
console.log('存储值(盐:哈希):', stored.slice(0, 40) + '...');
console.log('同密码两次存储值不同(盐随机):', stored !== hashPassword('P@ssw0rd!'));
console.log('正确密码校验:', verifyPassword('P@ssw0rd!', stored)); // true
console.log('错误密码校验:', verifyPassword('wrong-pass', stored)); // false
console.log('哈希长度固定 64 字节:', stored.split(':')[1].length === 128);
